sys_script_fix.script:
var eventId = 'EVT0001010'; // Replace with your specific event sys_id

var taskGR = new GlideRecord('x_1790229_event_ma_event_task'); // Replace with your actual task table name
taskGR.addQuery('u_event_id.number', eventId); // Assuming 'event' is the reference field pointing to the Event
taskGR.query();

while (taskGR.next()) {
    gs.info('Task Name: ' + taskGR.getValue('u_task_name'));

    gs.info('Status: ' + taskGR.getDisplayValue('u_status'));

}
